query DiscussionList($owner: String!, $name: String!, $first: Int!) {
  repository(owner: $owner, name: $name) {
    hasDiscussionsEnabled
    discussionCategories(first: 10) {
      totalCount
      nodes { id name slug emoji isAnswerable }
    }
    discussions(first: $first, orderBy: {field: UPDATED_AT, direction: DESC}) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes {
        id number title body locked upvoteCount isAnswered
        category { id slug name isAnswerable }
        answer { id body }
        author { login }
        comments(first: 5) {
          totalCount
          nodes {
            id body upvoteCount isAnswer
            author { login }
            replies(first: 5) { totalCount nodes { id body } }
          }
        }
      }
    }
  }
}
